package io.rift.cronos;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.webkit.*;
import androidx.webkit.*;
import org.json.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Origin- and main-frame-scoped EXPORT ONLY. No read, RPC, credential, wallet or arbitrary-path operation. */
public final class NativeExports implements AutoCloseable {
 public static final int PICK_DESTINATION=94;
 private final Activity activity;private final String origin;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private State active,picker;private boolean closed;
 private static final class State {
  final String id,name,mime,sha,token=UUID.randomUUID().toString();final long size;final JavaScriptReplyProxy reply;
  AlertDialog consent;Uri destination;File stage;ExportSession session;volatile boolean cancelled;boolean inFlight;Runnable timeout;
  State(String id,String name,String mime,long size,String sha,JavaScriptReplyProxy reply){this.id=id;this.name=name;this.mime=mime;this.size=size;this.sha=sha;this.reply=reply;}
 }
 public NativeExports(Activity activity,String origin){this.activity=activity;this.origin=origin;}
 public boolean install(WebView web){if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))return false;
  WebViewCompat.addWebMessageListener(web,"RiftFiles",Collections.singleton(origin),(view,message,sourceOrigin,isMainFrame,reply)->{
   if(closed||!isMainFrame||!FilePolicy.sameOrigin(origin,sourceOrigin.toString()))return;
   String raw=message.getData();if(raw==null||raw.length()>40000)return;String id="";
   try{JSONObject data=new JSONObject(JsonBudget.check(raw,40000,8));id=data.getString("id");if(!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException("Invalid request ID");String op=data.getString("op");
    if(op.equals("begin")){begin(data,reply);return;}
    State s=active;if(s==null||!s.id.equals(id))throw new IllegalStateException("No active export");
    if(op.equals("cancel")){stop(s,"Export cancelled");return;}
    if(!s.token.equals(data.optString("token"))||s.session==null||s.inFlight)throw new IllegalStateException("Invalid export session/state");
    if(op.equals("chunk")){String encoded=data.getString("data");if(encoded.length()>32768||!encoded.matches("[A-Za-z0-9+/]*={0,2}"))throw new IllegalArgumentException("Invalid export chunk");byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.NO_WRAP);int seq=data.getInt("seq");s.inFlight=true;io.execute(()->{try{if(s.cancelled)throw new IOException();s.session.append(seq,bytes,SystemClock.elapsedRealtime());ui.post(()->{s.inFlight=false;if(active==s&&!s.cancelled)send(reply,s.id,"chunk",s.token,seq,null);});}catch(Exception e){ui.post(()->stop(s,"Export chunk rejected"));}});return;}
    if(op.equals("end")){s.inFlight=true;io.execute(()->finish(s,reply));return;}
    throw new IllegalArgumentException("Unsupported export operation");
   }catch(Exception e){State s=active;if(s!=null&&s.id.equals(id))stop(s,"Export request rejected");else send(reply,id,"error",null,-1,"Export request rejected");}
  });return true;
 }
 private void begin(JSONObject data,JavaScriptReplyProxy reply) throws Exception {
  String id=data.getString("id");if(active!=null||picker!=null){send(reply,id,"error",null,-1,"Another export is active");return;}
  String name=FilePolicy.filename(data.getString("name")),mime=FilePolicy.mime(name),sha=data.getString("sha256");long size=data.getLong("size");if(!mime.equals(data.getString("mime"))||size<0||size>FilePolicy.EXPORT_MAX||!sha.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Invalid file metadata");
  State s=new State(id,name,mime,size,sha,reply);active=s;s.timeout=()->stop(s,"Export timed out");ui.postDelayed(s.timeout,180000);
  s.consent=new AlertDialog.Builder(activity).setTitle("Save generated data file?").setMessage(name+"\n"+size+" bytes\nOnly the data generated by this page will be saved, at a location you choose. No connection credentials are supplied by Android.").setPositiveButton("Choose location",(d,w)->{if(active!=s)return;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType(mime);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,name);try{picker=s;activity.startActivityForResult(intent,PICK_DESTINATION);}catch(Exception e){picker=null;stop(s,"No document provider available");}}).setNegativeButton("Cancel",(d,w)->stop(s,"Export cancelled")).setOnCancelListener(d->stop(s,"Export cancelled")).show();
 }
 public void onResult(int result,Intent data){State s=picker;picker=null;if(s==null||active!=s||s.cancelled)return;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){stop(s,"Export cancelled");return;}Uri uri=data.getData();if(!"content".equals(uri.getScheme())){stop(s,"Document-provider URI required");return;}s.destination=uri;s.inFlight=true;
  io.execute(()->{try{if(s.cancelled)throw new IOException();s.stage=File.createTempFile("rift-export-",".tmp",activity.getCacheDir());s.session=new ExportSession(new FileOutputStream(s.stage),s.size,s.sha,SystemClock.elapsedRealtime());ui.post(()->{s.inFlight=false;if(active==s&&!s.cancelled)send(s.reply,s.id,"ready",s.token,-1,null);else cleanup(s);});}catch(Exception e){ui.post(()->stop(s,"Export staging unavailable"));}});
 }
 private void finish(State s,JavaScriptReplyProxy reply){try{if(s.cancelled)throw new IOException();s.session.finish(SystemClock.elapsedRealtime());if(!s.session.verified())throw new IOException();try(InputStream input=new FileInputStream(s.stage);OutputStream output=activity.getContentResolver().openOutputStream(s.destination,"wt")){if(output==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(s.cancelled)throw new IOException();output.write(buffer,0,n);}output.flush();}ui.post(()->{if(active==s&&!s.cancelled){ui.removeCallbacks(s.timeout);active=null;send(reply,s.id,"done",s.token,-1,null);}cleanup(s);});}catch(Exception e){ui.post(()->stop(s,"Export failed; destination may be empty or partial"));}}
 private void send(JavaScriptReplyProxy reply,String id,String status,String token,int seq,String error){try{JSONObject response=new JSONObject().put("id",id).put("status",status);if(token!=null)response.put("token",token);if(seq>=0)response.put("seq",seq);if(error!=null)response.put("error",error);if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))reply.postMessage(response.toString());}catch(Exception ignored){}}
 private void cleanup(State s){try{if(s.session!=null)s.session.close();}catch(Exception ignored){}if(s.stage!=null)s.stage.delete();}
 private void stop(State s,String reason){s.cancelled=true;if(s.consent!=null){s.consent.dismiss();s.consent=null;}if(s.timeout!=null)ui.removeCallbacks(s.timeout);if(active==s)active=null;send(s.reply,s.id,"error",null,-1,reason);if(!io.isShutdown())io.execute(()->cleanup(s));}
 public void navigation(){if(active!=null)stop(active,"Page changed; export cancelled. A chosen destination may remain empty/partial");}
 @Override public void close(){if(closed)return;closed=true;navigation();io.shutdown();}
}
